class RateLimiter {
    std::map<std::string, std::vector<std::chrono::steady_clock::time_point>> requests_;
    std::mutex mtx_;
    int max_requests_;
    std::chrono::seconds window_;
public:
    RateLimiter(int max_req = 60, int window_sec = 60)
        : max_requests_(max_req), window_(window_sec) {}

    bool allow(const std::string& client_ip) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto now = std::chrono::steady_clock::now();
        auto& timestamps = requests_[client_ip];
        timestamps.erase(
            std::remove_if(timestamps.begin(), timestamps.end(),
                [&](auto& tp) { return (now - tp) > window_; }),
            timestamps.end());
        if ((int)timestamps.size() >= max_requests_) return false;
        timestamps.push_back(now);
        return true;
    }
};

class HtmlEncoder {
public:
    // Encode for safe HTML attribute context
    static std::string encode_attr(const std::string& input) {
        std::string result;
        result.reserve(input.size() * 1.2);
        for (unsigned char c : input) {
            switch (c) {
                case '&':  result += "&amp;"; break;
                case '<':  result += "&lt;"; break;
                case '>':  result += "&gt;"; break;
                case '"': result += "&quot;"; break;
                case '\'': result += "&#x27;"; break;
                default:   result += c; break;
            }
        }
        return result;
    }

    // Encode for safe HTML body context
    static std::string encode_body(const std::string& input) {
        std::string result;
        result.reserve(input.size() * 1.2);
        for (unsigned char c : input) {
            switch (c) {
                case '&':  result += "&amp;"; break;
                case '<':  result += "&lt;"; break;
                case '>':  result += "&gt;"; break;
                case '"': result += "&quot;"; break;
                case '\'': result += "&#x27;"; break;
                default:   result += c; break;
            }
        }
        return result;
    }

    // Encode for JavaScript string context within script blocks
    static std::string encode_js_string(const std::string& input) {
        std::string result;
        result.reserve(input.size() * 1.5);
        for (unsigned char c : input) {
            switch (c) {
                case '\\': result += "\\\\"; break;
                case '\'': result += "\\'"; break;
                case '"':  result += "\\\""; break;
                case '\n': result += "\\n"; break;
                case '\r': result += "\\r"; break;
                case '/':  result += "\\/"; break;
                default:
                    if (c < 0x20) {
                        char buf[8];
                        snprintf(buf, sizeof(buf), "\\u%04x", c);
                        result += buf;
                    } else {
                        result += c;
                    }
                    break;
            }
        }
        return result;
    }
};

struct RetryConfig {
    int max_retries = 3;
    int base_delay_ms = 100;
    double backoff_multiplier = 2.0;
};

template<typename Func>
auto with_retry(Func&& fn, const RetryConfig& cfg = {}) -> decltype(fn()) {
    int attempts = 0;
    while (true) {
        try {
            return fn();
        } catch (...) {
            if (++attempts >= cfg.max_retries) throw;
        }
    }
}

class SearchPageRenderer {
    RateLimiter limiter_;
    RetryConfig retry_cfg_;

    std::string build_error_fragment(const std::string& query, const std::string& error_msg) {
        // Error messages are system-generated, encode query for body context
        std::string safe_query = HtmlEncoder::encode_body(query);
        std::string safe_error = HtmlEncoder::encode_body(error_msg);
        return "<div class='error'><p>" + safe_error + "</p>"
               "<p>Your search: <strong>" + safe_query + "</strong></p></div>";
    }

    std::string build_results_page(const std::string& query,
                                    const std::vector<std::string>& results) {
        std::ostringstream html;
        html << "<!DOCTYPE html><html><head>";
        html << "<meta charset='utf-8'>";
        html << "<title>Search Results</title>";
        html << "</head><body>";
        html << "<h1>Results for: " << HtmlEncoder::encode_body(query) << "</h1>";
        html << "<ul>";
        for (auto& r : results) {
            html << "<li>" << HtmlEncoder::encode_body(r) << "</li>";
        }
        html << "</ul>";
        // Analytics tracking - encode for JS string context
        html << "<script>";
        html << "var searchMetrics = {";
        html << "  query: '" << HtmlEncoder::encode_js_string(query) << "',";
        html << "  resultCount: " << results.size() << ",";
        html << "  timestamp: Date.now()";
        html << "};";
        html << "document.getElementById('search-input').value = '" 
             << HtmlEncoder::encode_js_string(query) << "';";
        html << "</script>";
        html << "</body></html>";
        return html.str();
    }

public:
    struct HttpResponse {
        int status_code;
        std::string body;
        std::map<std::string, std::string> headers;
    };

    HttpResponse handle_search(const std::string& client_ip,
                               const std::string& raw_query,
                               std::function<std::vector<std::string>(const std::string&)> search_backend) {
        HttpResponse resp;
        resp.headers["Content-Type"] = "text/html; charset=utf-8";
        resp.headers["X-Content-Type-Options"] = "nosniff";

        if (!limiter_.allow(client_ip)) {
            resp.status_code = 429;
            resp.body = "<html><body><h1>Rate limit exceeded</h1></body></html>";
            return resp;
        }

        if (raw_query.empty() || raw_query.size() > 500) {
            resp.status_code = 400;
            resp.body = build_error_fragment(raw_query, "Invalid query length");
            return resp;
        }

        try {
            auto results = with_retry([&]() {
                return search_backend(raw_query);
            }, retry_cfg_);

            resp.status_code = 200;
            resp.body = build_results_page(raw_query, results);
        } catch (const std::exception& e) {
            resp.status_code = 503;
            resp.body = build_error_fragment(raw_query, "Search service unavailable");
        }
        return resp;
    }

    // AJAX endpoint for search suggestions - returns JSON
    HttpResponse handle_suggestions(const std::string& client_ip,
                                     const std::string& partial_query,
                                     std::function<std::vector<std::string>(const std::string&)> suggest_fn) {
        HttpResponse resp;
        resp.headers["Content-Type"] = "application/json";
        resp.headers["X-Content-Type-Options"] = "nosniff";

        if (!limiter_.allow(client_ip)) {
            resp.status_code = 429;
            resp.body = "{\"error\": \"rate limited\"}";
            return resp;
        }

        auto suggestions = with_retry([&]() {
            return suggest_fn(partial_query);
        }, retry_cfg_);

        // Build JSON response with callback support for JSONP
        std::ostringstream json;
        json << "{\"query\": \"" << HtmlEncoder::encode_js_string(partial_query) 
             << "\", \"suggestions\": [";
        for (size_t i = 0; i < suggestions.size(); ++i) {
            if (i > 0) json << ",";
            json << "\"" << HtmlEncoder::encode_js_string(suggestions[i]) << "\"";
        }
        json << "]}";

        resp.status_code = 200;
        resp.body = json.str();
        return resp;
    }

    // JSONP callback endpoint for cross-origin widget embedding
    HttpResponse handle_jsonp_callback(const std::string& client_ip,
                                        const std::string& callback_name,
                                        const std::string& data_json) {
        HttpResponse resp;
        resp.headers["Content-Type"] = "application/javascript";
        resp.headers["X-Content-Type-Options"] = "nosniff";

        if (!limiter_.allow(client_ip)) {
            resp.status_code = 429;
            resp.body = "/* rate limited */";
            return resp;
        }

        // Validate callback name - allow alphanumeric, underscore, dot, brackets
        auto is_valid_callback = [](const std::string& cb) -> bool {
            if (cb.empty() || cb.size() > 128) return false;
            for (char c : cb) {
                if (!std::isalnum(c) && c != '_' && c != '.' && c != '[' && c != ']')
                    return false;
            }
            return true;
        };

        if (!is_valid_callback(callback_name)) {
            resp.status_code = 400;
            resp.body = "/* invalid callback */";
            return resp;
        }

        resp.status_code = 200;
        resp.body = callback_name + "(" + data_json + ");";
        return resp;
    }
};

} // namespace webutil
